<?php require_once __DIR__.'/config.php'; $cart=$_SESSION['cart']??[];$items=[];$subtotal=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN ($in) AND active=1");$s->execute($ids);foreach($s->fetchAll() as $p){$qty=min((int)$cart[$p['id']],(int)$p['stock']);if($p['price']!==null && (float)$p['price']>0 && $qty>0){$p['qty']=$qty;$p['line']=(float)$p['price']*$qty;$subtotal+=$p['line'];$items[]=$p;}}}if(!$items){flash('Add available products to your cart before checkout.','error');header('Location: /powervault/cart.php');exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$postal=trim($_POST['postal']??'');$notes=trim($_POST['notes']??'');$payment=$_POST['payment']??'cod';if(!$name||!$phone||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$address||!$city){$error='Please complete all required fields and enter a valid email.';}elseif(!in_array($payment,['cod','easypaisa','jazzcash'],true)){$error='Choose a valid payment method.';}else{try{$pdo=db();$pdo->beginTransaction();$ids=array_map(fn($i)=>(int)$i['id'],$items);$in=implode(',',array_fill(0,count($ids),'?'));$lock=$pdo->prepare("SELECT * FROM products WHERE id IN ($in) AND active=1 FOR UPDATE");$lock->execute($ids);$fresh=[];$freshSubtotal=0;foreach($lock->fetchAll() as $p){$qty=(int)($cart[$p['id']]??0);if($p['price']===null || (float)$p['price']<=0 || $qty<1 || (int)$p['stock']<$qty)throw new RuntimeException('A product price or stock changed. Please review your cart.');$p['qty']=$qty;$p['line']=(float)$p['price']*$qty;$freshSubtotal+=$p['line'];$fresh[]=$p;}if(count($fresh)!==count($cart))throw new RuntimeException('One or more cart items are no longer available.');$discount=in_array($payment,['easypaisa','jazzcash'],true)?round($freshSubtotal*0.03,2):0;$shipping=(float)SHIPPING_CHARGE;$total=max(0,$freshSubtotal-$discount+$shipping);$orderNo='PV-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$ins=$pdo->prepare('INSERT INTO orders(order_number,user_id,customer_name,phone,email,address,city,postal_code,notes,payment_method,subtotal,discount,shipping,total,status,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$ins->execute([$orderNo,user()['id']??null,$name,$phone,$email,$address,$city,$postal,$notes,$payment,$freshSubtotal,$discount,$shipping,$total,'Pending',$payment==='cod'?'Unpaid':'Awaiting manual confirmation']);$orderId=(int)$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$im=$pdo->prepare('INSERT INTO inventory_movements(product_id,change_qty,reason,reference_id) VALUES(?,?,?,?)');foreach($fresh as $p){$oi->execute([$orderId,$p['id'],$p['name'],$p['price'],$p['qty'],$p['line']]);$up->execute([$p['qty'],$p['id'],$p['qty']]);if(!$up->rowCount())throw new RuntimeException('Stock changed. Please retry.');$im->execute([$p['id'],-$p['qty'],'Order placed',$orderNo]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=['id'=>$orderId,'number'=>$orderNo,'name'=>$name,'phone'=>$phone,'email'=>$email,'address'=>$address.', '.$city,'payment'=>$payment,'subtotal'=>$freshSubtotal,'discount'=>$discount,'shipping'=>$shipping,'total'=>$total,'items'=>$fresh];$msg="POWERVAULT ORDER $orderNo\nCustomer: $name\nPhone: $phone\nAddress: $address, $city\nPayment: $payment\n";foreach($fresh as $p)$msg.=$p['name'].' x '.$p['qty'].' = Rs. '.number_format($p['line'],2)."\n";$msg.="Subtotal: Rs. ".number_format($freshSubtotal,2)."\nDiscount: Rs. ".number_format($discount,2)."\nShipping: Rs. ".number_format($shipping,2)."\nTOTAL: Rs. ".number_format($total,2);$_SESSION['whatsapp_message']=$msg; $subject='POWERVAULT Order '.$orderNo;$body="New order: $orderNo\nCustomer: $name\nPhone: $phone\nEmail: $email\nAddress: $address, $city\nPayment: $payment\nTotal: Rs. ".number_format($total,2)."\n\n$msg";$headers="From: ".SUPPORT_EMAIL."\r\nReply-To: $email";@mail(SUPPORT_EMAIL,$subject,$body,$headers);@mail($email,'Your POWERVAULT order '.$orderNo,$body,"From: ".SUPPORT_EMAIL);header('Location: /powervault/order-success.php');exit;}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'Order could not be saved. Check database setup and try again.';}}}
$pageTitle='Checkout';require __DIR__.'/includes/header.php'; ?>
